 "content": "def transform(grid):
    """Connect the marked points with a median-centered orthogonal backbone."""
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if len(points) < 2:
        return out

    rows = sorted(r for r, _ in points)
    cols = sorted(c for _, c in points)
    rmin, rmax = rows[0], rows[-1]
    cmin, cmax = cols[0], cols[-1]

    # Use the longer dimension for the backbone; ties choose horizontal.
    if (rmax - rmin) > (cmax - cmin):
        spine_c = cols[(len(cols) - 1) // 2]
        for r in range(rmin, rmax + 1):
            if out[r][spine_c] == 0:
                out[r][spine_c] = 3
        for r, c in points:
            for cc in range(min(c, spine_c), max(c, spine_c) + 1):
                if out[r][cc] == 0:
                    out[r][cc] = 3
    else:
        spine_r = rows[(len(rows) - 1) // 2]
        for c in range(cmin, cmax + 1):
            if out[spine_r][c] == 0:
                out[spine_r][c] = 3
        for r, c in points:
            for rr in range(min(r, spine_r), max(r, spine_r) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    return out
